package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	line := scanner.Text()
	parts := strings.Fields(line)

	total, _ := strconv.Atoi(parts[0])
	front, _ := strconv.Atoi(parts[1])
	back, _ := strconv.Atoi(parts[2])

	diff := total - front

	if diff > back {
		fmt.Println(back + 1)
	} else {
		fmt.Println(diff)
	}
}

